internal final class AVACreateInventQualityOrderService  extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
/// <param name = "_contract">AVACreateInventQualityOrderContract</param>
public void process(AVACreateInventQualityOrderContract _contract)
{
    ProdId ProdId = _contract.parmProdId();
    ProdTable   prodTable = ProdTable::find(ProdId);
    InventQualityOrderTable inventQualityOrderTable;
    NumberSeq numberSeq;


    if (ProdId)
    {
        ttsbegin;
        numberSeq = NumberSeq::newGetNum(NumberSeqReference::findReference(extendedTypeNum(InventQualityOrderId)));
        inventQualityOrderTable.QualityOrderId = numberSeq.num();
        inventQualityOrderTable.initFromBuffer(prodTable);
        inventQualityOrderTable.TestGroupId = InventTable::find(prodTable.ItemId).AVAInventTestGroupId;
        inventQualityOrderTable.initFromInventTestGroup();
        inventQualityOrderTable.initQtyByFindingAssoc();
        if (!inventQualityOrderTable.Qty)
        {
            inventQualityOrderTable.Qty = 1;
        }
        inventqualityordertable.insert();
        ttscommit;
    }
}
